// Fontes embutidas do RG Digital (base64) — garantem tipografia idêntica no PDF final.
const RG_SANS_B64 = "";
const RG_OCRB_B64 = "";

export const RG_FONT_FACE = `
  @font-face {
    font-family: 'RGDigital';
    font-style: normal;
    font-weight: 400;
    src: url(data:font/truetype;charset=utf-8;base64,${RG_SANS_B64}) format('truetype');
  }
  @font-face {
    font-family: 'RGOcrb';
    font-style: normal;
    font-weight: 400;
    src: url(data:font/truetype;charset=utf-8;base64,${RG_OCRB_B64}) format('truetype');
  }
`;
